local function bxor(a, b)
  if type(bit) == "table" and type(bit.bxor) == "function" then
    return bit.bxor(a, b)
  end
  local r = 0
  for i = 0, 7 do
    if math.floor(a / 2^i) % 2 ~= math.floor(b / 2^i) % 2 then
      r = r + 2^i
    end
  end
  return r
end

local lookup = {}
for i = 1, #B64 do lookup[B64:sub(i, i)] = i - 1 end

local function b64decode(s)
  s = s:gsub("[^%w+/=]", "")
  local out, o, i = {}, 1, 1
  while i <= #s do
    local a = lookup[s:sub(i, i)]
    local b = lookup[s:sub(i + 1, i + 1)]
    if a == nil or b == nil then break end
    local cch, dch = s:sub(i + 2, i + 2), s:sub(i + 3, i + 3)
    local c = (cch ~= "=") and lookup[cch] or 0
    local d = (dch ~= "=") and lookup[dch] or 0
    if (cch ~= "=" and c == nil) or (dch ~= "=" and d == nil) then break end
    out[o] = string.char(a * 4 + math.floor(b / 16)); o = o + 1
    if cch ~= "=" then
      out[o] = string.char((b % 16) * 16 + math.floor(c / 4)); o = o + 1
    end
    if dch ~= "=" then
      out[o] = string.char((c % 4) * 64 + d); o = o + 1
    end
    i = i + 4
  end
  return table.concat(out)
end

local function payload_checksum(s)
  local sum = 0
  for i = 1, #s do
    sum = (sum + s:byte(i) * ((i % 251) + 1)) % 0x100000000
  end
  return sum
end

local packed = b64decode(BLOB)
local decoded = {}
local klen = #KEY
for i = 1, #packed do
  decoded[i] = string.char(bxor(packed:byte(i), KEY:byte(((i - 1) % klen) + 1)))
end
local src = table.concat(decoded)

if payload_checksum(src) ~= EXPECT then
  print("DBHELP: проверка целостности не прошла")
  return
end

local fn, err = loadstring(src, "@DBHELP.lua")
if not fn then
  print("DBHELP: ошибка загрузки: " .. tostring(err))
  return
end
fn()
